#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: verd #49, AUR + Homebrew publishing
# ──────────────────────────────────────────────────────────────────────────

ENV_FILE=/dev/null   # nothing is persisted to .env; values go to GitHub secrets
TOTAL_STAGES=4; [[ "${WITH_AUR:-0}" == 1 ]] && TOTAL_STAGES=8   # AUR signups paused; WITH_AUR=1 to include
REPO="moneytosms/verd"
TAP="moneytosms/homebrew-tap"
AUR_KEYFILE="$HOME/.ssh/aur_verd"

banner "verd: set up AUR + Homebrew publishing"

if [[ "${WITH_AUR:-0}" == 1 ]]; then
stage "Generate a dedicated AUR SSH key"
say "goreleaser pushes to the AUR over SSH. It needs a key WITHOUT a passphrase."
if [[ -f "$AUR_KEYFILE" ]]; then
  note "$AUR_KEYFILE already exists, reusing it."
else
  ssh-keygen -t ed25519 -N "" -C "goreleaser-verd" -f "$AUR_KEYFILE" >/dev/null
  say "✓ created $AUR_KEYFILE (+ .pub)"
fi
pause

stage "Create your AUR account"
say "Skip if you already have one."
open_url "https://aur.archlinux.org/register"
step "Fill username, email, and the captcha. Submit."
step "Click the confirmation link in the email AUR sends you."
pause "Account created and confirmed?"

stage "Add the public key to your AUR account"
open_url "https://aur.archlinux.org/login"
step "Log in, click your username (top right) → 'My Account' → Edit."
step "Paste this into the 'SSH Public Key' box:"
printf '\n%s\n\n' "$(cat "${AUR_KEYFILE}.pub")"
step "Enter your password at the bottom and click 'Update'."
pause "Key saved on AUR?"
say "Testing SSH access..."
if ssh -i "$AUR_KEYFILE" -o IdentitiesOnly=yes -o StrictHostKeyChecking=accept-new \
     -o BatchMode=yes aur@aur.archlinux.org help >/dev/null 2>&1; then
  say "✓ AUR accepted the key"
else
  warn "AUR rejected the key. Re-check the pasted key (one line, no edits), then re-run."
  confirm "Continue anyway?" || exit 1
fi

stage "Store AUR_KEY as a GitHub secret"
say "The package 'verd-bin' is created automatically by the first goreleaser push."
say "Check https://aur.archlinux.org/packages?K=verd-bin first: the name must be free."
set_secret AUR_KEY "$(cat "$AUR_KEYFILE")"
pause
fi

stage "Create the Homebrew tap repo"
if gh repo view "$TAP" >/dev/null 2>&1; then
  note "$TAP already exists, skipping."
else
  confirm "Create public repo $TAP?" || exit 1
  gh repo create "$TAP" --public --add-readme \
    --description "Homebrew tap for verd" >/dev/null
  say "✓ created https://github.com/$TAP"
fi
pause

stage "Create a fine-grained token for the tap"
say "goreleaser's default GITHUB_TOKEN can't write to another repo, so it needs this."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: verd-tap-publish. Expiration: pick 1 year (note the date!)."
step "Repository access → 'Only select repositories' → homebrew-tap."
step "Permissions → Repository permissions → Contents → 'Read and write'."
step "Click 'Generate token' and copy it (starts github_pat_)."
ask_secret HOMEBREW_TAP_TOKEN "Paste the token:"
if [[ "$(GH_TOKEN="$HOMEBREW_TAP_TOKEN" gh api "repos/$TAP" --jq .permissions.push 2>/dev/null)" == "true" ]]; then
  say "✓ token can push to $TAP"
else
  warn "token can't push to $TAP. Check repo access + Contents: Read and write."
  confirm "Continue anyway?" || exit 1
fi
set_secret HOMEBREW_TAP_TOKEN "$HOMEBREW_TAP_TOKEN"

stage "Commit the goreleaser + workflow changes"
say "Already edited for you: .goreleaser.yaml (aurs, brews), release.yml, release-check.yml"
git status --short .goreleaser.yaml .github
if confirm "Commit and push these to the current branch?"; then
  git add .goreleaser.yaml .github/workflows
  git commit -m "feat: publish to AUR and Homebrew"
  git push
else
  SKIPPED+=("commit + push .goreleaser.yaml and .github/workflows")
fi

stage "Cut a release and verify"
ask TAG "Tag to release (e.g. v0.1.5):"
if [[ -n "$TAG" ]] && confirm "Tag $TAG and push? This publishes to AUR + Homebrew."; then
  git tag "$TAG" && git push origin "$TAG"
  sleep 5
  RUN=$(gh run list --workflow release --limit 1 --json databaseId -q '.[0].databaseId')
  gh run watch "$RUN" --exit-status || warn "release run failed: gh run view $RUN --log-failed"
else
  SKIPPED+=("tag and push a release (git tag vX.Y.Z && git push origin vX.Y.Z)")
fi
say "Now verify on a real machine:"
[[ "${WITH_AUR:-0}" == 1 ]] && step "yay -S verd-bin && verd --version"
step "brew install moneytosms/tap/verd && verd --version"
if [[ "${WITH_AUR:-0}" == 1 ]] && confirm "Both work? Close issue #49?"; then
  gh issue close 49 --repo "$REPO" --comment "AUR and Homebrew publishing verified." >/dev/null
  say "✓ closed #49"
fi

finish
